template <int Case>
__global__ __launch_bounds__(256) void dot_case_kernel(
    const std::uint32_t *__restrict__ left,
    const std::uint32_t *__restrict__ right, std::size_t count,
    device_tables tables, double *__restrict__ partials) {
  extern __shared__ unsigned char scratch[];
  auto context = decoder<Case>::prepare(tables, scratch);
  double sum = 0.0;
  const auto stride = static_cast<std::size_t>(gridDim.x) * blockDim.x;
  for (auto index = static_cast<std::size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
       index < count; index += stride) {
    const auto a = decoder<Case>::decode(left[index], context);
    const auto b = decoder<Case>::decode(right[index], context);
    sum = fma(a, b, sum);
  }
  auto *shared = reinterpret_cast<double *>(scratch + decoder<Case>::shared_bytes);
  shared[threadIdx.x] = sum;
  __syncthreads();
  for (int offset = 128; offset != 0; offset >>= 1) {
    if (threadIdx.x < offset) shared[threadIdx.x] += shared[threadIdx.x + offset];
    __syncthreads();
  }
  if (threadIdx.x == 0) partials[blockIdx.x] = shared[0];
}

